class Solution {
public:
    bool areSentencesSimilar(vector<string>& sentence1,
                             vector<string>& sentence2,
                             vector<vector<string>>& similarPairs) {
        if (sentence1.size() != sentence2.size()) {
            return false;
        }
        unordered_map<string, unordered_set<string>> related;
        for (const auto& pair : similarPairs) {
            related[pair[0]].insert(pair[1]);
            related[pair[1]].insert(pair[0]);
        }
        for (int i = 0; i < static_cast<int>(sentence1.size()); ++i) {
            if (sentence1[i] != sentence2[i]
                && !related[sentence1[i]].count(sentence2[i])) {
                return false;
            }
        }
        return true;
    }
};
